#!/usr/bin/env python3
"""Writes bet-abi-v1.json: golden mirage-bet ABI v1 records (TASK-018).

Independent oracle: the bytes are packed here with Python's struct module from
the offsets in docs/SPECS_SIMULATION_ENGINES.md section 4, not by the
TypeScript encoder or the Rust decoder that the tests compare against them.
Run from the repository root: python3 tests/fixtures/wasm-abi/generate.py
"""
import json
import math
import struct
from pathlib import Path

DT_S = 1.0 / 400.0
ROTORS = [
    {"id": 7, "bladeCount": 2, "spinSign": 1, "azimuthSamples": 8, "polarId": 0,
     "radiusM": 0.127, "rootCutoutM": 0.02, "hubPositionBodyM": [0.1, -0.1, -0.02],
     "hubToBody": [1.0, 0.0, 0.0, 0.0], "shaftInertiaKgM2": 2.5e-5, "bearingViscousNmPerRadS": 1e-6,
     "radialStationM": [0.04, 0.08, 0.12], "chordM": [0.02, 0.018, 0.012],
     "twistRad": [0.3, 0.2, 0.1], "quadratureWidthM": [0.04, 0.04, 0.027]},
    {"id": 8, "bladeCount": 3, "spinSign": -1, "azimuthSamples": 16, "polarId": 1,
     "radiusM": 0.2, "rootCutoutM": 0.0, "hubPositionBodyM": [-0.15, 0.15, -0.03],
     "hubToBody": [math.sqrt(0.5), 0.0, 0.0, math.sqrt(0.5)], "shaftInertiaKgM2": 8e-5,
     "bearingViscousNmPerRadS": 0.0, "radialStationM": [0.05, 0.15], "chordM": [0.03, 0.02],
     "twistRad": [0.25, -0.05], "quadratureWidthM": [0.1, 0.1]},
]
INPUT = {"densityKgM3": 1.225, "dynamicViscosityPaS": 1.81e-5, "speedOfSoundMps": 340.29, "rotors": [
    {"airVelocityAtHubHubMps": [1.0, -2.0, 3.0], "bodyAngularVelocityHubRadS": [0.1, 0.2, -0.3],
     "collectivePitchRad": 0.05, "cyclicCosRad": 0.01, "cyclicSinRad": -0.02, "motorTorqueMagnitudeNm": 0.04},
    {"airVelocityAtHubHubMps": [0.0, 0.0, -5.0], "bodyAngularVelocityHubRadS": [0.0, 0.0, 0.0],
     "collectivePitchRad": 0.0, "cyclicCosRad": 0.0, "cyclicSinRad": 0.0, "motorTorqueMagnitudeNm": 0.0},
]}


def put(buf, offset, fmt, *values):
    struct.pack_into("<" + fmt, buf, offset, *values)


def rotor_record(r):
    rec = bytearray(2160)
    put(rec, 0, "IIiIII", r["id"], r["bladeCount"], r["spinSign"], len(r["radialStationM"]),
        r["azimuthSamples"], r["polarId"])
    put(rec, 24, "dd", r["radiusM"], r["rootCutoutM"])
    put(rec, 40, "3d", *r["hubPositionBodyM"])
    put(rec, 64, "4d", *r["hubToBody"])
    put(rec, 96, "dd", r["shaftInertiaKgM2"], r["bearingViscousNmPerRadS"])
    for base, key in ((112, "radialStationM"), (624, "chordM"), (1136, "twistRad"), (1648, "quadratureWidthM")):
        for i, value in enumerate(r[key]):
            put(rec, base + 8 * i, "d", value)
    return rec


def config_bytes():
    header = bytearray(64)
    put(header, 0, "IIII", 1, 64 + 2160 * len(ROTORS), len(ROTORS), 2160)
    put(header, 16, "d", DT_S)
    return header + b"".join(rotor_record(r) for r in ROTORS)


def input_bytes():
    header = bytearray(64)
    put(header, 0, "II", len(INPUT["rotors"]), 96)
    put(header, 8, "3d", INPUT["densityKgM3"], INPUT["dynamicViscosityPaS"], INPUT["speedOfSoundMps"])
    records = []
    for r in INPUT["rotors"]:
        rec = bytearray(96)
        put(rec, 0, "3d", *r["airVelocityAtHubHubMps"])
        put(rec, 24, "3d", *r["bodyAngularVelocityHubRadS"])
        put(rec, 48, "4d", r["collectivePitchRad"], r["cyclicCosRad"], r["cyclicSinRad"], r["motorTorqueMagnitudeNm"])
        records.append(rec)
    return header + b"".join(records)


fixture = {
    "description": "mirage-bet ABI v1 golden records; generated by tests/fixtures/wasm-abi/generate.py (Python struct, little-endian)",
    "abiVersion": 1,
    "config": {"dtS": DT_S, "rotors": ROTORS},
    "configBytes": len(config_bytes()),
    "configHex": config_bytes().hex(),
    "input": INPUT,
    "inputBytes": len(input_bytes()),
    "inputHex": input_bytes().hex(),
    "requiredArenaBytes": 64 + len(config_bytes()) + 64 * len(ROTORS),
}
out = Path(__file__).with_name("bet-abi-v1.json")
out.write_text(json.dumps(fixture, indent=2) + "\n")
print(f"wrote {out}: config {fixture['configBytes']} B, input {fixture['inputBytes']} B")
